/// Reading `.pblog` log dumps.
///
/// A dump is the device's `RepRecord` stream without the flash sector framing,
/// written as a sequence of `[u32 little-endian length][record bytes]`. The
/// reference implementation is `calypso_core::fixtures::read_dump`; this is the
/// client side of the same contract, and the fixtures in `assets/fixtures/` are
/// generated by the firmware's own encoders, so decoding them here is a real
/// wire-format check.
library;

import 'dart:typed_data';

import '../model/uuid.dart';
import 'calypso.pb.dart';

/// The result of reading a dump.
class DumpReadResult {
  const DumpReadResult(this.records, {this.truncated = false});

  /// Records that were fully present and decoded, in order.
  final List<RepRecord> records;

  /// True if the dump ended mid-record (a torn capture) or a record failed to
  /// decode. The records before it are still returned: a partial capture is
  /// still useful, it just must not be silently treated as complete.
  final bool truncated;
}

/// Reads the `[u32 LE length][RepRecord]` framing.
DumpReadResult readDump(Uint8List bytes) {
  final records = <RepRecord>[];
  var pos = 0;
  while (pos + 4 <= bytes.length) {
    final length = ByteData.sublistView(bytes, pos, pos + 4).getUint32(0, Endian.little);
    final start = pos + 4;
    if (start + length > bytes.length) {
      return DumpReadResult(records, truncated: true);
    }
    try {
      records.add(RepRecord.fromBuffer(bytes.sublist(start, start + length)));
    } catch (_) {
      // A frame whose length was intact but whose payload was corrupt.
      return DumpReadResult(records, truncated: true);
    }
    pos = start + length;
  }
  return DumpReadResult(records, truncated: pos != bytes.length);
}

/// The rep summaries in a dump, in the order they appear (oldest first).
List<RepSummary> summariesOf(List<RepRecord> records) =>
    records.where((r) => r.hasSummary()).map((r) => r.summary).toList();

/// The rep UUID of a decoded summary, as canonical text.
String? summaryUuid(RepSummary summary) => uuidFromBytes(summary.repUuid);

/// The rep UUID of a decoded trace chunk, as canonical text.
String? chunkUuid(TraceChunk chunk) => uuidFromBytes(chunk.repUuid);

/// The trace chunks belonging to [uuid], ordered by chunk index.
///
/// The device streams chunks in order, but re-requesting a trace is allowed, so
/// ordering here rather than trusting arrival order keeps the caller honest.
List<TraceChunk> traceChunksFor(List<RepRecord> records, String uuid) {
  final chunks = records
      .where((r) => r.hasTrace() && chunkUuid(r.trace) == uuid)
      .map((r) => r.trace)
      .toList()
    ..sort((a, b) => a.index.compareTo(b.index));
  return chunks;
}
